e="{{ old('project_reference') }}"></div><div class="field full" id="reference-field" style="display:none"><label>Reference invoice</label><select name="reference_invoice_id"><option value="">Select approved invoice</option>@foreach($references as $reference)<option value="{{ $reference->id }}">{{ $reference->invoice_number }} · {{ $reference->customer->name ?? '' }}</option>@endforeach</select></div><div class="field full"><label>Notes</label><textarea name="notes" maxlength="2000" placeholder="Payment terms or internal reference">{{ old('notes') }}</textarea></div></div></div></div>
