<script>(function(){let body=document.getElementById('invoice-lines'),template=document.getElementById('line-template'),index=0;function add(){let row=template.content.firstElementChild.cloneNode(true),i=index++;row.querySelectorAll('[data-name]').forEach(el=>el.name='lines['+i+']['+el.dataset.name+']');row.querySelector('[data-item-select]').addEventListener('change',function(){let o=this.options[this.selectedIndex];row.querySelector('[name$="[item_id]"]').value=this.value; if(this.value){row.querySelector('[name$="[description]"]').value=o.dataset.name;row.querySelector('[name$="[description_ar]"]').value=o.dataset.ar||'';row.querySelector('[name$="[unit_code]"]').value=o.dataset.unit;row.querySelector('[name$="[unit_price]"]').value=o.dataset.price;row.querySelector('[name$="[tax_category]"]').value=o.dataset.tax;syncTax(row);}});row.querySelector('[name$="[tax_category]"]').addEventListener('change',()=>syncTax(row));row.querySelector('[data-remove-line]').addEventListener('click',()=>{if(body.children.length>1)row.remove();});body.appendChild(row);}function syncTax(row){row.querySelector('[name$="[tax_rate_units]"]').value=row.querySelector('[name$="[tax_category]"]').value==='standard'?'1500':'0';}document.getElementById('add-line').addEventListener('click',add);document.getElementById('document-type').addEventListener('change',function(){document.getElementById('reference-field').style.display=this.value==='invoice'?'none':'block';});add();})();</script>
